// AccountingPeriod Accounting period issued by the center (§10.4). Nodes never redefine periods in local time.
type AccountingPeriod struct {
	// PeriodEnd Exclusive. The agent samples at period_end so intervals do not cross periods (§10.9).
	PeriodEnd time.Time `json:"period_end"`

	// PeriodId Accounting period ID generated by the central service. V1 uses the UTC calendar month `YYYY-MM` (§10.4, pending business decision on the period type).
	PeriodId PeriodId `json:"period_id"`

	// PeriodStart Inclusive.
	PeriodStart time.Time `json:"period_start"`
}

// AgentBootstrap One-time NetBird setup credential delivered only over agent mTLS (D-015, §6.4). TEST ONLY examples are not usable keys.
type AgentBootstrap struct {
	// ExpiresAt UTC expiry of the bootstrap credential. The server also enforces the separate delivery deadline.
	ExpiresAt time.Time `json:"expires_at"`

	// ExternalKeyId Opaque NetBird setup key ID, retained for reconciliation.
	ExternalKeyId string `json:"external_key_id"`

	// SetupKey One-off bootstrap secret; never log, audit or replay it.
	SetupKey string `json:"setup_key"`
}

// Architecture Supported node CPU architectures (§3.2).
type Architecture string

// AuditEvent Redacted audit event (§9.1, §16.4). Configuration history, never member
// browsing history. `enrollment.created` puts `token_sha256` in
// `changes.after`: the lowercase hex SHA-256 of the one-time token, the
// same value as `Enrollment.token_sha256`. Property names ending in
// `_sha256` are digests and are never redacted.
type AuditEvent struct {
	// Action Dotted action name, for example `node.publish`.
	Action string `json:"action"`
	Actor  struct {
		Id   nullable.Nullable[openapi_types.UUID] `json:"id"`
		Type AuditEventActorType                   `json:"type"`
	} `json:"actor"`
	AuditEventId openapi_types.UUID `json:"audit_event_id"`

	// Changes Redacted before/after differences. Never secrets, tokens or full
	// payment payloads. Property names ending in `_sha256` are digests
	// and are never redacted, including `token_sha256`.
	Changes struct {
		After  nullable.Nullable[map[string]interface{}] `json:"after"`
		Before nullable.Nullable[map[string]interface{}] `json:"before"`
	} `json:"changes"`
	OccurredAt  time.Time                             `json:"occurred_at"`
	OperationId nullable.Nullable[openapi_types.UUID] `json:"operation_id"`
	RequestId   nullable.Nullable[openapi_types.UUID] `json:"request_id"`
	Resource    ResourceRef                           `json:"resource"`
	Result      AuditEventResult                      `json:"result"`
}

// AuditEventActorType defines model for AuditEvent.Actor.Type.
type AuditEventActorType string

// AuditEventResult defines model for AuditEvent.Result.
type AuditEventResult string

// AuditEventList defines model for AuditEventList.
type AuditEventList struct {
	Items      []AuditEvent              `json:"items"`
	NextCursor nullable.Nullable[string] `json:"next_cursor"`
}

