// FairUsePayload Fair-use policy revision (§11.1). Thresholds and rates are pending
// business decisions; start in shadow mode.
//
// Validation rules enforced on create (§11.1):
//  1. `tiers` is non-empty and `tiers[0].threshold_bytes` is "0", so tiers
//     cover usage completely from zero with no gap.
//  2. `threshold_bytes` is strictly increasing. Usage U is in tier i when
//     tiers[i].threshold_bytes <= U < tiers[i+1].threshold_bytes; the last
//     tier is unbounded above. U equal to a threshold enters that tier.
//  3. Every tier has both `down_bps` and `up_bps`; all rates are
//     non-negative integers.
//  4. Rates are non-increasing and `priority` is non-decreasing from one
//     tier to the next (a higher tier is never faster or more favored), so
//     within one period the tier only stays or moves to a stricter one.
//  5. Every tier rate is at least `minimum_rate` in each direction.
//  6. Overrides have a finite `valid_until` in the future, a reason and an
//     actor; at most one override per member.
//
// A missing tier is never treated as unlimited.
type FairUsePayload struct {
	AccountingBasis struct {
		// Measure upload_bytes plus download_bytes (§11.1).
		Measure FairUsePayloadAccountingBasisMeasure `json:"measure"`

		// MeteringVersion Metering definition (§10.1). Never silently change the meaning of a version.
		MeteringVersion MeteringVersion `json:"metering_version"`

		// PeriodType Accounting period type (recommended default UTC calendar month; pending decision, §10.4).
		PeriodType FairUsePayloadAccountingBasisPeriodType `json:"period_type"`
	} `json:"accounting_basis"`

	// EffectiveAt When this revision's mode takes effect. Shadow results are never reported as throttling.
	EffectiveAt time.Time `json:"effective_at"`

	// EffectivePeriod Recommended default next_full_period; immediate is an explicit emergency adjustment (§11.1).
	EffectivePeriod FairUsePayloadEffectivePeriod `json:"effective_period"`

	// MinimumRate Basic usable rate floor (§11.1); the formal value is a pending decision.
	MinimumRate RatePair `json:"minimum_rate"`

	// Mode shadow records would_apply_tier only and never shapes; enforce generates member policy generations (§11.2).
	Mode      FairUsePayloadMode `json:"mode"`
	Overrides []FairUseOverride  `json:"overrides"`
	Tiers     []FairUseTier      `json:"tiers"`
}

// FairUsePayloadAccountingBasisMeasure upload_bytes plus download_bytes (§11.1).
type FairUsePayloadAccountingBasisMeasure string

// FairUsePayloadAccountingBasisPeriodType Accounting period type (recommended default UTC calendar month; pending decision, §10.4).
type FairUsePayloadAccountingBasisPeriodType string

// FairUsePayloadEffectivePeriod Recommended default next_full_period; immediate is an explicit emergency adjustment (§11.1).
type FairUsePayloadEffectivePeriod string

