// UsageEvent Immutable usage event (§10.5). One event per sampling interval holds every
// changed device record of the node. Unique key: (node_id,
// node_incarnation_id, event_seq); meter_epoch_id is content, not part of the
// key (§10.6). `payload_sha256` is the lowercase hex SHA-256 of the RFC 8785
// canonical JSON of this event object without the `payload_sha256` member
// and without any batch wrapper (`canonjson.HashHex(event,
// "payload_sha256")`). Resends reuse the stored payload byte for byte.
// `gap` is present only when quality is `gap`. interval_end is after
// interval_start; intervals are half-open.
type UsageEvent struct {
	// EventSeq Starts at 1 per node incarnation and increases forever.
	EventSeq decstr.U64 `json:"event_seq"`

	// Gap Gap record (§10.7). Unknown bytes are never reported as zero-complete or estimated into official usage.
	Gap           *UsageGap `json:"gap,omitempty"`
	IntervalEnd   time.Time `json:"interval_end"`
	IntervalStart time.Time `json:"interval_start"`

	// MeterEpochId Counter generation; changes on counter rebuild, never resets event_seq.
	MeterEpochId openapi_types.UUID `json:"meter_epoch_id"`

	// MeteringVersion Metering definition (§10.1). Never silently change the meaning of a version.
	MeteringVersion   MeteringVersion    `json:"metering_version"`
	NodeId            openapi_types.UUID `json:"node_id"`
	NodeIncarnationId openapi_types.UUID `json:"node_incarnation_id"`
	PayloadSha256     string             `json:"payload_sha256"`

	// Quality complete, gap (data known missing) or boundary_estimated (period split by time proportion) (§10.7, §10.9).
	Quality       UsageQuality            `json:"quality"`
	Records       []UsageRecord           `json:"records"`
	SchemaVersion UsageEventSchemaVersion `json:"schema_version"`
}

// UsageEventSchemaVersion defines model for UsageEvent.SchemaVersion.
type UsageEventSchemaVersion int

// UsageEventResult defines model for UsageEventResult.
type UsageEventResult struct {
	// Error Present for conflict (USAGE_EVENT_CONFLICT) and rejected (VALIDATION_FAILED, METER_PATH_INVALID, ...).
	Error nullable.Nullable[struct {
		// Code Stable error codes (§13.11, §14.6 and domain codes). The HTTP status and
		// default retryable flag of each code are defined in `pkg/apierr`; the
		// contracts tests keep this enum identical to that table. Codes marked
		// node-local in `pkg/apierr` are reported mainly inside agent payloads
		// (update results, observations). ARTIFACT_INVALID, ISOLATION_BASELINE_MISSING,
		// METER_EPOCH_CHANGE, the nine node enforcement verification codes added
		// in revision 8, and AWAITING_MEMBER_GRANTS (D-071) are report-only and
		// have no HTTP response status.
		// NOT_IMPLEMENTED is transitional HTTP 501, retryable false; documented
		// endpoints must not ship with it in a release.
		// Node enforcement verification (§13.11) is the address-free group the node
		// agent reports. These codes appear in `NodeError.code` and in the
		// serving-check `error_code` of `ObservationReport`. They never appear in
		// browser-facing `Error.code`.
		// METER_PATH_INVALID: the accounting path is not the one this generation claimed: hook, NAT position, source identity, or a counter that can be skipped (§10.3).
		// ISOLATION_BASELINE_MISSING: member forwarding is not held at the fail-closed boot ruleset (§8.2, §17.1).
		// GENERATION_MISMATCH: the kernel ruleset is not the requested generation.
		// HOOK_PRIORITY_MISMATCH: a base chain hook or priority drifted (§8.2).
		// COUNTER_ORDER_INVALID: an accept can skip the per-device counters, including an established/related accept placed before the lease check (§10.2, §16.3).
		// FLOWTABLE_BYPASS: a flowtable or offload could bypass the counters (§10.3).
		// DEVICE_CLASS_MISSING: a device binding has no counter or class.
		// METER_EPOCH_CHANGE: a named counter went backwards or disappeared. Callers must open a new meter epoch and must not hide the gap (§10.7).
		// QOS_CLASS_MISSING: the HTB parent or a member class is missing or wrong (§11.4, §11.5).
		// MARK_SEMANTICS_VIOLATED: a rule writes skb mark or conntrack mark. NetBird owns 0x1BD00-0x1BDFF (§11.4).
		// ISOLATION_POLICY_INVALID: the allow/deny policy itself does not match.
		// PROBE_UNBOUNDED: a synthetic-probe set element has no kernel timeout, so the exception would outlive the health check (§13.9).
		// AWAITING_MEMBER_GRANTS: The node lease for this generation is inside its anchored deadline and `config_generation` equals the desired generation, but `lease.members` is empty while desired `device_bindings` is non-empty. The agent renews on the D-067 schedule (one heartbeat, then doubling, capped at 60 seconds). This is not a deadline failure and not a malformed policy.
		Code    ErrorCode    `json:"code"`
		Fields  []FieldError `json:"fields"`
		Message string       `json:"message"`
	}] `json:"error"`
	EventSeq decstr.U64 `json:"event_seq"`

	// Status Per-event outcome (§10.6). accepted and duplicate are persisted; conflict and rejected are not counted.
	Status UsageEventResultStatus `json:"status"`
}

